import { readProjectFile } from './project-files.mjs';

/** A checked-in name keeps generated bytes stable across different clone directories. */
export async function projectName(root) {
  const text = await readProjectFile(root, 'package.json');
  if (text !== null) {
    try {
      const name = JSON.parse(text).name;
      if (typeof name === 'string' && name.trim()) return name;
    } catch { /* Project-model diagnostics report invalid package metadata. */ }
  }
  return 'project';
}
